using System;using System.IO;using System.IO.Compression;using System.Collections.Generic;using System.Management;using System.Text.RegularExpressions;using System.Web.Script.Serialization;using System.Diagnostics;
static class EnvironmentReport {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=40000000};
 public static string Redact(string text){foreach(string value in new[]{Environment.UserName,Environment.MachineName})if(!String.IsNullOrEmpty(value)&&value.Length>2)text=text.Replace(value,"[redacted]");text=Regex.Replace(text,@"github_pat_[A-Za-z0-9_]+","[credential]");text=Regex.Replace(text,@"#[a-fA-F0-9]{64}","#[credential]");text=Regex.Replace(text,@"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}","[email]");return Regex.Replace(text,@"[A-Za-z]:\\(?:\\)?[^""\r\n]*","[local path]");}
 static void Add(ZipArchive zip,string name,string text){using(var writer=new StreamWriter(zip.CreateEntry(name).Open()))writer.Write(Redact(text));}
 public static void Collect(ZipArchive zip){
  var result=new Dictionary<string,object>{{"schema",1},{"at",DateTime.UtcNow.ToString("o")},{"os",Environment.OSVersion.VersionString},{"os64Bit",Environment.Is64BitOperatingSystem},{"runtime",Environment.Version.ToString()},{"fixtureDiscovery","Ordinary DMX has no fixture identity feedback. Patch and profile data below describe the configured PC show, not discovered fixtures."},{"excluded",new[]{"USB serial numbers","account database","PINs","passwords","access credentials","LAN certificate private keys","network addresses","vendor device keys"}},{"remainingUnknowns",new[]{"device-wide standalone tables outside scene reads","flash allocation and commit sequence","verified standalone write and restore","physical light response"}}};
  var drivers=new List<object>();result["usbDrivers"]=drivers;
  result["sdkPublicApiScope"]=new[]{"USB enumeration and open/close","firmware version","universe count","DMX configuration read/write","live DMX universe read/write"};
  result["standaloneReadScope"]=new[]{"configuration","configured scene headers","trigger payloads","per-step fade and hold","used channel values per universe","repeat-read comparison"};
  result["testScope"]= "Read-only standalone investigation. No live output, erase, scene-memory write or restore test; none is claimed as verified.";
  try{using(var search=new ManagementObjectSearcher("SELECT DeviceName, Manufacturer, DriverProviderName, DriverVersion, DriverDate, InfName FROM Win32_PnPSignedDriver WHERE DeviceID LIKE '%VID_0483&PID_A1DF%'"))using(var rows=search.Get())foreach(ManagementObject row in rows)using(row){var item=new Dictionary<string,object>();foreach(string key in new[]{"DeviceName","Manufacturer","DriverProviderName","DriverVersion","DriverDate","InfName"})item[key]=row[key];drivers.Add(item);}}catch(Exception e){result["driverQueryError"]=e.GetType().Name;}
  string data=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"LifeAC-Lighting");
  foreach(string file in new[]{"install.json","show.json","settings.json"}){try{string path=Path.Combine(data,file);if(!File.Exists(path))continue;if(new FileInfo(path).Length>12000000)throw new InvalidDataException();var source=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path));var selected=new Dictionary<string,object>();string[] keys=file=="show.json"?new[]{"schema","revision","sourceHash","fixtures","profiles","scenes","standalone","midiMappings","folders"}:file=="settings.json"?new[]{"midiName","midiEnabled","autoTakeover","takeoverSceneId","lanEnabled"}:new[]{"version"};foreach(string key in keys)if(source.ContainsKey(key))selected[key]=source[key];Add(zip,"environment/"+file,Json.Serialize(selected));}catch(Exception e){result[file+"Error"]=e.GetType().Name;}}
  foreach(string suffix in new[]{"",".1",".2",".3"})try{string path=Path.Combine(data,"logs","lighting.jsonl"+suffix);if(File.Exists(path)&&new FileInfo(path).Length<=2200000)Add(zip,"environment/lighting.jsonl"+suffix,File.ReadAllText(path));}catch(Exception e){result["logReadError"]=e.GetType().Name;}
  Add(zip,"environment/report.json",Json.Serialize(result));
 }
}
